CREATE TABLE IF NOT EXISTS families(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(80) UNIQUE NOT NULL,logo_url TEXT,owner_id UUID NOT NULL REFERENCES users(id),level INT NOT NULL DEFAULT 1,total_points BIGINT NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS family_members(family_id UUID REFERENCES families(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(20) NOT NULL DEFAULT 'member',joined_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(family_id,user_id));
CREATE TABLE IF NOT EXISTS inventory_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,item_type VARCHAR(30) NOT NULL,item_key VARCHAR(100) NOT NULL,item_name VARCHAR(120) NOT NULL,quantity INT NOT NULL DEFAULT 1,starts_at TIMESTAMPTZ,expires_at TIMESTAMPTZ,is_active BOOLEAN NOT NULL DEFAULT TRUE,metadata JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_inventory_user ON inventory_items(user_id,is_active);
CREATE TABLE IF NOT EXISTS entrance_effects(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(100) NOT NULL,animation_url TEXT NOT NULL,duration_ms INT NOT NULL DEFAULT 4000,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS frames(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(100) NOT NULL,image_url TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS wip_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(100) NOT NULL,level INT NOT NULL DEFAULT 1,duration_days INT NOT NULL,price_coins BIGINT NOT NULL DEFAULT 0,is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS user_wip(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,level INT NOT NULL DEFAULT 1,starts_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS dealer_accounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(100) NOT NULL,owner_user_id UUID REFERENCES users(id),coin_balance BIGINT NOT NULL DEFAULT 0,commission_bps INT NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS dealer_transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dealer_id UUID NOT NULL REFERENCES dealer_accounts(id),admin_id UUID REFERENCES users(id),user_id UUID REFERENCES users(id),type VARCHAR(30) NOT NULL,coin_amount BIGINT NOT NULL,description TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS global_gift_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),gift_transaction_id UUID REFERENCES gift_transactions(id),room_id UUID REFERENCES rooms(id),sender_id UUID REFERENCES users(id),receiver_id UUID REFERENCES users(id),coin_amount BIGINT NOT NULL,display_level INT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_global_gift_created ON global_gift_events(created_at DESC);
